   sh(sub, "init", "-q", "-b", "main"); sh(sub, "config", "user.email", "a@b"); sh(sub, "config", "user.name", "t");
   put(sub, "s.txt", "1\n"); sh(sub, "add", "-A"); sh(sub, "commit", "-qm", "s1");
+  return sub;
+}
